// Authorization for inbound mail.
//
// Order matters and is fail-closed at every step:
//   1. loop guard      — never act on our own outbound address
//   2. auto-generated  — no replies to robots (that is how loops start)
//   3. allowlist       — exact addr-spec after RFC 5322-ish normalization
//   4. DMARC           — pinned authserv-id, must be dmarc=pass
//
// The routing token is NOT consulted here. It routes; it does not authorize.
// See docs/SECURITY.md §2.2.

import type { ResolvedConfig } from "./config.ts"
import { dmarcPasses, findTrustedAuthResults, isAutoGenerated, normalizeAddress, type HeaderLike } from "./reply-parse.ts"

export type AuthzDenial =
	| "no-from"
	| "self"
	| "auto-generated"
	| "not-allowlisted"
	| "allowlist-empty"
	| "dmarc-missing"
	| "dmarc-untrusted"
	| "dmarc-failed"

export type AuthzResult =
	| { ok: true; from: string }
	| { ok: false; reason: AuthzDenial }

export interface AuthzInput {
	/** Raw `From:` header value, display name included. */
	from: string | undefined
	headers: HeaderLike
}

export function authorize(input: AuthzInput, config: ResolvedConfig): AuthzResult {
	const from = normalizeAddress(input.from)
	if (!from) return { ok: false, reason: "no-from" }

	// 1. Loop guard: the pi account must never be treated as the human.
	//    `mail.to` is the HUMAN's address, so it must not be used here — doing so
	//    rejected every genuine reply (the human is the one writing to us).
	const self = normalizeAddress(config.mail.smtp.user) ?? normalizeAddress(config.mail.imap.user)
	if (self && from === self) return { ok: false, reason: "self" }

	// 2. Never answer robots.
	if (isAutoGenerated(input.headers)) return { ok: false, reason: "auto-generated" }

	// 3. Allowlist. An empty list denies everything.
	const allow = config.security.allowFrom.map((a) => normalizeAddress(a)).filter((a): a is string => Boolean(a))
	if (allow.length === 0) return { ok: false, reason: "allowlist-empty" }
	if (!allow.includes(from)) return { ok: false, reason: "not-allowlisted" }

	// 4. DMARC pinned to our relay.
	if (config.security.requireDmarcPass) {
		const trustedId = config.security.trustedAuthservId
		if (!trustedId) return { ok: false, reason: "dmarc-untrusted" }
		const ar = findTrustedAuthResults(input.headers, trustedId)
		if (!ar) return { ok: false, reason: "dmarc-missing" }
		if (!dmarcPasses(ar)) return { ok: false, reason: "dmarc-failed" }
	}

	return { ok: true, from }
}
